with valid as (select *, quarter(event_time) event_time_quarter, coalesce(page, 'UNKNOWN') resolved_page from web_events where page is not null) select date_trunc('week', event_time) as week_start, count(distinct page) as distinct_pages, sum(event_time_quarter) filter (where page = '/search') as search_total_event_time_quarter, (unix_timestamp(max(event_time)) - unix_timestamp(min(event_time))) / 60 as duration_min from valid group by week_start having (unix_timestamp(max(event_time)) - unix_timestamp(min(event_time))) / 60 > 0 order by duration_min
